public class Solution {
    public string AbbreviateProduct(int left, int right) {
        System.Numerics.BigInteger product = 1;
        for (int i = left; i <= right; i++) {
            product *= i;
        }

        int c = 0;
        while (product % 10 == 0) {
            product /= 10;
            c++;
        }

        string s = product.ToString();
        if (s.Length <= 10) {
            return s + "e" + c;
        }

        return s.Substring(0, 5) + "..." + s.Substring(s.Length - 5, 5) + "e" + c;
    }
}
```

