    private class DSU {
        public int[] Parent;
        public int[] Size;
        public DSU(int n) {
            Parent = new int[n];
            Size = new int[n];
            for (int i = 0; i < n; i++) {
                Parent[i] = i;
                Size[i] = 1;
            }
        }
        public int Find(int x) {
            if (Parent[x] != x) {
                Parent[x] = Find(Parent[x]);
            }
            return Parent[x];
        }
        public void Union(int a, int b) {
            int ra = Find(a);
            int rb = Find(b);
            if (ra == rb) return;
            if (Size[ra] < Size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            Parent[rb] = ra;
            Size[ra] += Size[rb];
        }
    }

