public class Solution {
    public bool KLengthApart(int[] nums, int k) {
        int last = -k - 1;
        for (int i = 0; i < nums.Length; i++) {
            if (nums[i] == 1) {
                if (i - last <= k) return false;
                last = i;
            }
        }
        return true;
    }
}
