```csharp
public class Solution {
    public int[] NumSmallerByFrequency(string[] queries, string[] words) {
        int[] wordFreq = new int[words.Length];
        for (int i = 0; i < words.Length; i++) {
            wordFreq[i] = GetSmallestCharFrequency(words[i]);
        }

        System.Array.Sort(wordFreq);

        int[] answer = new int[queries.Length];
        for (int i = 0; i < queries.Length; i++) {
            int queryFreq = GetSmallestCharFrequency(queries[i]);
            int count = 0;
            for (int j = 0; j < wordFreq.Length; j++) {
                if (wordFreq[j] > queryFreq) {
                    count++;
                }
            }
            answer[i] = count;
        }

        return answer;
    }

    private int GetSmallestCharFrequency(string s) {
        char smallest = s[0];
        int frequency = 1;

        for (int i = 1; i < s.Length; i++) {
            if (s[i] < smallest) {
                smallest = s[i];
                frequency = 1;
            } else if (s[i] == smallest) {
                frequency++;
            }
        }

        return frequency;
    }
}
```

