public class Solution {
    public IList<int> EventualSafeNodes(int[][] graph) {
        int n = graph.Length;
        int[] outDegree = new int[n];
        List<int>[] reverse = new List<int>[n];
        for (int i = 0; i < n; i++) {
            reverse[i] = new List<int>();
        }
        for (int u = 0; u < n; u++) {
            outDegree[u] = graph[u].Length;
            foreach (int v in graph[u]) {
                reverse[v].Add(u);
            }
        }
        Queue<int> q = new Queue<int>();
        for (int i = 0; i < n; i++) {
            if (outDegree[i] == 0) {
                q.Enqueue(i);
            }
        }
        bool[] safe = new bool[n];
        while (q.Count > 0) {
            int v = q.Dequeue();
            safe[v] = true;
            foreach (int u in reverse[v]) {
                outDegree[u]--;
                if (outDegree[u] == 0) {
                    q.Enqueue(u);
                }
            }
        }
        List<int> result = new List<int>();
        for (int i = 0; i < n; i++) {
            if (safe[i]) {
                result.Add(i);
            }
        }
        return result;
    }
}
