using System;
using System.Collections.Generic;

public class MKAverage {
    private class Fenwick {
        private int[] count;
        private long[] sum;
        private int n;

        public Fenwick(int n) {
            this.n = n;
            count = new int[n + 1];
            sum = new long[n + 1];
        }

        public void Add(int idx, int deltaCount, long deltaSum) {
            while (idx <= n) {
                count[idx] += deltaCount;
                sum[idx] += deltaSum;
                idx += idx & -idx;
            }
        }

        public int QueryCount(int idx) {
            int result = 0;
            while (idx > 0) {
                result += count[idx];
                idx -= idx & -idx;
            }
            return result;
        }

        public long QuerySum(int idx) {
            long result = 0;
            while (idx > 0) {
                result += sum[idx];
                idx -= idx & -idx;
            }
            return result;
        }

        public int FindKth(int k) {
            int idx = 0;
            int bitMask = 1;
            while ((bitMask << 1) <= n) {
                bitMask <<= 1;
            }

            for (int d = bitMask; d != 0; d >>= 1) {
                int next = idx + d;
                if (next <= n && count[next] < k) {
                    idx = next;
                    k -= count[next];
                }
            }

            return idx + 1;
        }
    }

    private const int MAX_VALUE = 100000;

    private int m;
    private int k;
    private Queue<int> window;
    private Fenwick fenwick;

    public MKAverage(int m, int k) {
        this.m = m;
        this.k = k;
        window = new Queue<int>();
        fenwick = new Fenwick(MAX_VALUE);
    }

    public void AddElement(int num) {
        if (window.Count == m) {
            int old = window.Dequeue();
            fenwick.Add(old, -1, -old);
        }

        window.Enqueue(num);
        fenwick.Add(num, 1, num);
    }

    public int CalculateMKAverage() {
        if (window.Count < m) {
            return -1;
        }

        long sumFirstMInusK = SumSmallestK(m - k);
        long sumFirstK = SumSmallestK(k);

        long middleSum = sumFirstMInusK - sumFirstK;
        int middleCount = m - 2 * k;

        return (int)(middleSum / middleCount);
    }

    private long SumSmallestK(int kth) {
        if (kth <= 0) {
            return 0;
        }

        int value = fenwick.FindKth(kth);
        int countBefore = fenwick.QueryCount(value - 1);
        long sumBefore = fenwick.QuerySum(value - 1);
        int needed = kth - countBefore;

        return sumBefore + (long)needed * value;
    }
}

