public class Solution {
    public int LargestMagicSquare(int[][] grid) {
        int m = grid.Length;
        int n = grid[0].Length;
        int maxK = Math.Min(m, n);

        for (int k = maxK; k >= 1; k--) {
            for (int r = 0; r + k <= m; r++) {
                for (int c = 0; c + k <= n; c++) {
                    if (IsMagic(grid, r, c, k)) {
                        return k;
                    }
                }
            }
        }

        return 1;
    }

    private bool IsMagic(int[][] grid, int r, int c, int k) {
        int target = 0;
        for (int j = 0; j < k; j++) {
            target += grid[r][c + j];
        }

        for (int i = 0; i < k; i++) {
            int rowSum = 0;
            for (int j = 0; j < k; j++) {
                rowSum += grid[r + i][c + j];
            }
            if (rowSum != target) return false;
        }

        for (int j = 0; j < k; j++) {
            int colSum = 0;
            for (int i = 0; i < k; i++) {
                colSum += grid[r + i][c + j];
            }
            if (colSum != target) return false;
        }

        int diag1 = 0;
        int diag2 = 0;
        for (int i = 0; i < k; i++) {
            diag1 += grid[r + i][c + i];
            diag2 += grid[r + i][c + k - 1 - i];
        }

        return diag1 == target && diag2 == target;
    }
}
