```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public int MaxPoints(int[][] points) {
        int n = points.Length;
        if (n <= 2) return n;

        int max = 2;

        for (int i = 0; i < n; i++) {
            var slopes = new Dictionary<(int, int), int>();

            for (int j = 0; j < n; j++) {
                if (i == j) continue;

                int dx = points[j][0] - points[i][0];
                int dy = points[j][1] - points[i][1];

                if (dx < 0) {
                    dx = -dx;
                    dy = -dy;
                } else if (dx == 0 && dy < 0) {
                    dy = -dy;
                }

                int g = Gcd(Math.Abs(dx), Math.Abs(dy));
                dx /= g;
                dy /= g;

                var key = (dx, dy);
                slopes.TryGetValue(key, out int count);
                count++;
                slopes[key] = count;

                max = Math.Max(max, count + 1);
            }
        }

        return max;
    }

    private int Gcd(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }
}
