public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int[] pow3 = new int[numSlots + 1];
        pow3[0] = 1;
        for (int i = 1; i <= numSlots; i++) {
            pow3[i] = pow3[i - 1] * 3;
        }

        int total = pow3[numSlots];
        int[] dp = new int[total];
        int neg = -1000000000;

        for (int i = 0; i < total; i++) {
            dp[i] = neg;
        }
        dp[0] = 0;

        int n = nums.Length;
        int answer = 0;

        for (int mask = 0; mask < total; mask++) {
            if (dp[mask] == neg) continue;

            int used = 0;
            int temp = mask;
            for (int i = 0; i < numSlots; i++) {
                used += temp % 3;
                temp /= 3;
            }

            if (used >= n) {
                if (dp[mask] > answer) {
                    answer = dp[mask];
                }
                continue;
            }

            for (int slot = 0; slot < numSlots; slot++) {
                int digit = (mask / pow3[slot]) % 3;
                if (digit < 2) {
                    int nextMask = mask + pow3[slot];
                    int value = dp[mask] + (nums[used] & (slot + 1));
                    if (value > dp[nextMask]) {
                        dp[nextMask] = value;
                    }
                }
            }
        }

        return answer;
    }
}
