public class Solution {
    public int MaximumANDSum(int[] nums, int numSlots) {
        int[] pow3 = new int[numSlots + 1];
        pow3[0] = 1;
        for (int i=1;i<=numSlots;i++) pow3[i]=pow3[i-1]*3;
        int total = pow3[numSlots];
        int[] dp = new int[total];
        int NEG = int.MinValue/2;
        for (int i=0;i<total;i++) dp[i]=NEG;
        dp[0]=0;
        int n=nums.Length;
        int ans=0;
        for (int mask=0; mask<total; mask++) {
            if (dp[mask] == NEG) continue;
            int k=0, m=mask;
            for(int j=0;j<numSlots;j++){ k += m % 3; m /= 3; }
            if (k >= n) { if (dp[mask]>ans) ans=dp[mask]; continue; }
            for(int slot=0; slot<numSlots; slot++) {
                int digit = (mask / pow3[slot]) % 3;
                if (digit < 2) {
                    int nmask = mask + pow3[slot];
                    int val = dp[mask] + (nums[k] & (slot + 1));
                    if (val > dp[nmask]) dp[nmask] = val;
                }
            }
        }
        return ans;
    }
}

