public class Solution {
    public int MaxCompatibilitySum(int[][] students, int[][] mentors) {
        int m = students.Length;
        int n = students[0].Length;
        int[,] score = new int[m, m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < m; j++) {
                int cur = 0;
                for (int k = 0; k < n; k++) {
                    if (students[i][k] == mentors[j][k]) {
                        cur++;
                    }
                }
                score[i, j] = cur;
            }
        }

        int total = 1 << m;
        int[] dp = new int[total];
        for (int mask = 0; mask < total; mask++) {
            dp[mask] = -1;
        }
        dp[0] = 0;

        for (int mask = 0; mask < total; mask++) {
            if (dp[mask] < 0) continue;

            int student = PopCount(mask);
            if (student >= m) continue;

            for (int mentor = 0; mentor < m; mentor++) {
                if ((mask & (1 << mentor)) == 0) {
                    int nextMask = mask | (1 << mentor);
                    int nextScore = dp[mask] + score[student, mentor];
                    if (nextScore > dp[nextMask]) {
                        dp[nextMask] = nextScore;
                    }
                }
            }
        }

        return dp[total - 1];
    }

    private int PopCount(int x) {
        int count = 0;
        while (x > 0) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    }
}
