public class Solution {
    public int MaxEqualFreq(int[] nums) {
        int n = nums.Length;
        int maxVal = 0;
        foreach (int num in nums) {
            if (num > maxVal) maxVal = num;
        }

        int[] count = new int[maxVal + 1];
        int[] freq = new int[n + 2];
        int maxFreq = 0;
        int ans = 0;

        for (int i = 0; i < n; i++) {
            int x = nums[i];
            int c = count[x];

            if (c > 0) {
                freq[c]--;
            }

            c++;
            count[x] = c;
            freq[c]++;

            if (c > maxFreq) {
                maxFreq = c;
            }

            int len = i + 1;
            bool ok = false;

            if (maxFreq == 1) {
                ok = true;
            } else if (freq[maxFreq] == 1 &&
                       freq[maxFreq - 1] * (maxFreq - 1) + maxFreq == len) {
                ok = true;
            } else if (freq[1] == 1 &&
                       freq[maxFreq] * maxFreq + 1 == len) {
                ok = true;
            }

            if (ok) {
                ans = len;
            }
        }

        return ans;
    }
}
