```csharp
public class Solution {
    public int MaxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.Length;
        int[] pos = new int[n];
        long[] pref = new long[n + 1];

        for (int i = 0; i < n; i++) {
            pos[i] = fruits[i][0];
            pref[i + 1] = pref[i] + fruits[i][1];
        }

        int l = 0;
        long best = 0;

        for (int r = 0; r < n; r++) {
            while (l <= r) {
                int pl = pos[l];
                int pr = pos[r];
                long cost;

                if (startPos < pl) {
                    cost = (long)pr - startPos;
                } else if (startPos > pr) {
                    cost = (long)startPos - pl;
                } else {
                    long distL = startPos - pl;
                    long distR = pr - startPos;
                    cost = (long)(pr - pl) + (distL < distR ? distL : distR);
                }

                if (cost <= k) break;
                l++;
            }

            if (l <= r) {
                long sum = pref[r + 1] - pref[l];
                if (sum > best) best = sum;
            }
        }

        return (int)best;
    }
}
