```
using System;

public class Solution {
    public int MaxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.Length;
        int[] pos = new int[n];
        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pos[i] = fruits[i][0];
            pref[i + 1] = pref[i] + fruits[i][1];
        }

        int left = 0;
        long best = 0;
        for (int right = 0; right < n; right++) {
            while (left <= right) {
                int pl = pos[left];
                int pr = pos[right];
                long cost;
                if (startPos < pl) {
                    cost = (long)pr - startPos;
                } else if (startPos > pr) {
                    cost = (long)startPos - pl;
                } else {
                    cost = (long)(pr - pl) + Math.Min(startPos - pl, pr - startPos);
                }
                if (cost <= k) break;
                left++;
            }

            if (left <= right) {
                long sum = pref[right + 1] - pref[left];
                if (sum > best) best = sum;
            }
        }

        return (int)best;
    }
}
```
