public class Solution {
    public long MaxRunTime(int n, int[] batteries) {
        long total = 0;
        foreach (int b in batteries) total += b;
        long low = 0;
        long high = total / n;
        while (low < high) {
            long mid = low + (high - low + 1) / 2;
            long sum = 0;
            foreach (int b in batteries) {
                sum += Math.Min((long)b, mid);
                if (sum >= (long)n * mid) break; // optional
            }
            if (sum >= (long)n * mid) low = mid;
            else high = mid - 1;
        }
        return low;
    }
}

