```csharp
public class Solution {
    public int MaxStudents(char[][] seats) {
        int m = seats.Length;
        int n = seats[0].Length;
        int total = 1 << n;

        int[] available = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') {
                    mask |= 1 << j;
                }
            }
            available[i] = mask;
        }

        int[] dp = new int[total];
        for (int i = 0; i < total; i++) {
            dp[i] = -1;
        }
        dp[0] = 0;

        for (int row = 0; row < m; row++) {
            int[] nextDp = new int[total];
            for (int i = 0; i < total; i++) {
                nextDp[i] = -1;
            }

            for (int prev = 0; prev < total; prev++) {
                if (dp[prev] == -1) continue;

                for (int mask = 0; mask < total; mask++) {
                    if ((mask & available[row]) != mask) continue;
                    if ((mask & (mask << 1)) != 0) continue;
                    if ((prev & (mask << 1)) != 0) continue;
                    if ((prev & (mask >> 1)) != 0) continue;

                    int count = CountBits(mask);
                    int value = dp[prev] + count;
                    if (value > nextDp[mask]) {
                        nextDp[mask] = value;
                    }
                }
            }

            dp = nextDp;
        }

        int answer = 0;
        foreach (int value in dp) {
            if (value > answer) {
                answer = value;
            }
        }

        return answer;
    }

    private int CountBits(int x) {
        int count = 0;
        while (x > 0) {
            count += x & 1;
            x >>= 1;
        }
        return count;
    }
}
```

