public class Solution {
    public int MaxSumTwoNoOverlap(int[] nums, int firstLen, int secondLen) {
        return System.Math.Max(
            MaxSum(nums, firstLen, secondLen),
            MaxSum(nums, secondLen, firstLen)
        );
    }

    private int MaxSum(int[] nums, int len1, int len2) {
        int n = nums.Length;
        int[] prefix = new int[n + 1];

        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        int bestFirst = 0;
        int result = 0;

        for (int i = len1; i + len2 <= n; i++) {
            int firstSum = prefix[i] - prefix[i - len1];
            bestFirst = System.Math.Max(bestFirst, firstSum);

            int secondSum = prefix[i + len2] - prefix[i];
            result = System.Math.Max(result, bestFirst + secondSum);
        }

        return result;
    }
}
