public class Solution {
    public int MinMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.Length;
        int best = initial[0];
        int bestCount = int.MaxValue;

        foreach (int removed in initial) {
            bool[] infected = new bool[n];
            System.Collections.Generic.Queue<int> q = new System.Collections.Generic.Queue<int>();

            foreach (int s in initial) {
                if (s == removed) continue;
                infected[s] = true;
                q.Enqueue(s);
            }

            while (q.Count > 0) {
                int u = q.Dequeue();
                for (int v = 0; v < n; v++) {
                    if (v == removed) continue;
                    if (graph[u][v] == 1 && !infected[v]) {
                        infected[v] = true;
                        q.Enqueue(v);
                    }
                }
            }

            int count = 0;
            for (int i = 0; i < n; i++) {
                if (infected[i]) count++;
            }

            if (count < bestCount || (count == bestCount && removed < best)) {
                bestCount = count;
                best = removed;
            }
        }

        return best;
    }
}
