public class Solution {
    public int MinAreaRect(int[][] points) {
        var set = new HashSet<long>();
        foreach (var p in points) {
            set.Add(((long)p[0] << 32) | (uint)p[1]);
        }

        int minArea = int.MaxValue;
        int n = points.Length;

        for (int i = 0; i < n; i++) {
            int x1 = points[i][0];
            int y1 = points[i][1];

            for (int j = i + 1; j < n; j++) {
                int x2 = points[j][0];
                int y2 = points[j][1];

                if (x1 == x2 || y1 == y2) continue;

                long c1 = ((long)x1 << 32) | (uint)y2;
                long c2 = ((long)x2 << 32) | (uint)y1;

                if (set.Contains(c1) && set.Contains(c2)) {
                    int area = Math.Abs(x1 - x2) * Math.Abs(y1 - y2);
                    if (area < minArea) {
                        minArea = area;
                    }
                }
            }
        }

        return minArea == int.MaxValue ? 0 : minArea;
    }
}
