public class Solution {
    public int MinSessions(int[] tasks, int sessionTime) {
        int n = tasks.Length;
        int totalMasks = 1 << n;
        int[] sessions = new int[totalMasks];
        int[] used = new int[totalMasks];

        for (int mask = 0; mask < totalMasks; mask++) {
            sessions[mask] = int.MaxValue;
        }
        sessions[0] = 0;

        for (int mask = 0; mask < totalMasks; mask++) {
            if (sessions[mask] == int.MaxValue) continue;

            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;

                int next = mask | (1 << i);
                int nextSessions, nextUsed;

                if (sessions[mask] == 0) {
                    nextSessions = 1;
                    nextUsed = tasks[i];
