public class Solution {
    public int[] NextGreaterElements(int[] nums) {
        int n = nums.Length;
        int[] result = new int[n];
        for (int i = 0; i < n; i++) {
            result[i] = -1;
        }

        var stack = new System.Collections.Generic.Stack<int>();

        for (int i = 0; i < 2 * n; i++) {
            int idx = i % n;

            while (stack.Count > 0 && nums[stack.Peek()] < nums[idx]) {
                result[stack.Pop()] = nums[idx];
            }

            if (i < n) {
                stack.Push(idx);
            }
        }

        return result;
    }
}
