public class Solution {
    private const int MOD = 1000000007;
    private int[,] C;
    public int NumOfWays(int[] nums) {
        int n = nums.Length;
        C = new int[n+1, n+1];
        for (int i=0;i<=n;i++){
            C[i,0]=1;
            C[i,i]=1;
            for (int j=1;j<i;j++){
                C[i,j] = (int)(((long)C[i-1,j-1]+C[i-1,j])%MOD);
            }
        }
        long ways = Ways(nums.ToList());
        return (int)((ways - 1 + MOD) % MOD);
    }
    private long Ways(List<int> arr) {
        if (arr.Count <= 1) return 1;
        int root = arr[0];
        List<int> left = new List<int>();
        List<int> right = new List<int>();
        for (int i=1;i<arr.Count;i++){
            if (arr[i] < root) left.Add(arr[i]);
            else right.Add(arr[i]);
        }
        long leftWays = Ways(left);
        long rightWays = Ways(right);
        long comb = C[arr.Count - 1, left.Count];
        return comb * leftWays % MOD * rightWays % MOD;
    }
}

