public class Solution {
    public bool CanPartitionKSubsets(int[] nums, int k) {
        int n = nums.Length;
        int total = 0;
        foreach (int x in nums) total += x;
        if (total % k != 0) return false;
        int target = total / k;
        foreach (int x in nums) if (x > target) return false;
        int all = (1 << n) - 1;
        int[] sum = new int[1 << n];
        for (int mask = 1; mask <= all; mask++) {
            int lsb = mask & -mask;
            int i = 0;
            while ((lsb >> i) != 1) i++; // This finds bit index. But for lsb like 8, loop i=3. For mask up to 65536. Fine.
            sum[mask] = sum[mask ^ lsb] + nums[i];
        }
        bool[] dp = new bool[1 << n];
        dp[0] = true;
        for (int mask = 0; mask <= all; mask++) {
            if (!dp[mask]) continue;
            if (mask == all) return true;
            int rem = sum[mask] % target;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) continue;
                if (rem + nums[i] <= target) {
                    dp[mask | (1 << i)] = true;
                }
            }
        }
        return dp[all];
