public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int m = slices.Length;
        int n = m / 3;
        int[] withoutLast = new int[m - 1];
        int[] withoutFirst = new int[m - 1];

        for (int i = 0; i < m - 1; i++) {
            withoutLast[i] = slices[i];
            withoutFirst[i] = slices[i + 1];
        }

        return System.Math.Max(MaxLinear(withoutLast, n), MaxLinear(withoutFirst, n));
    }

    private int MaxLinear(int[] arr, int k) {
        int len = arr.Length;
        int neg = int.MinValue / 2;
        int[,] dp = new int[len + 1, k + 1];

        for (int i = 0; i <= len; i++) {
            for (int j = 0; j <= k; j++) {
                dp[i, j] = neg;
            }
        }

        dp[0, 0] = 0;

        for (int i = 1; i <= len; i++) {
            dp[i, 0] = 0;
            int maxJ = System.Math.Min(i, k);

            for (int j = 1; j <= maxJ; j++) {
                int best = dp[i - 1, j];

                if (j == 1) {
                    best = System.Math.Max(best, arr[i - 1]);
                }

                if (i >= 2 && dp[i - 2, j - 1] != neg) {
                    best = System.Math.Max(best, dp[i - 2, j - 1] + arr[i - 1]);
                }

                dp[i, j] = best;
            }
        }

        return dp[len, k];
    }
}
