public class Solution {
    public int MaxSizeSlices(int[] slices) {
        int m = slices.Length;
        int n = m / 3;
        int[] first = new int[m - 1];
        int[] second = new int[m - 1];
        for (int i = 0; i < m - 1; i++) {
            first[i] = slices[i];
            second[i] = slices[i + 1];
        }
        return Math.Max(MaxLinear(first, n), MaxLinear(second, n));
    }

    private int MaxLinear(int[] arr, int k) {
        int L = arr.Length;
        int[,] dp = new int[L + 1, k + 1];
        int neg = int.MinValue / 2;
        for (int i = 0; i <= L; i++)
            for (int j = 0; j <= k; j++)
                dp[i, j] = neg;
        dp[0, 0] = 0;
        // dp[i,0]=0 for all i maybe
        for (int i = 1; i <= L; i++) {
            dp[i, 0] = 0;
            int maxJ = Math.Min(i, k);
            for (int j = 1; j <= maxJ; j++) {
                int best = dp[i - 1, j];
                if (j == 1) {
                    best = Math.Max(best, arr[i - 1]);
                }
                if (i >= 2) {
                    int prev = dp[i - 2, j - 1];
                    if (prev != neg) best = Math.Max(best, prev + arr[i - 1]);
                }
                dp[i, j] = best;
            }
        }
        return dp[L, k];
    }
}

