public class Solution {
    public int RegionsBySlashes(string[] grid) {
        int n = grid.Length;
        int N = n * 3;
        bool[,] wall = new bool[N, N];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                char c = grid[i][j];
                int r = i * 3;
                int col = j * 3;

                if (c == '/') {
                    wall[r, col + 2] = true;
                    wall[r + 1, col + 1] = true;
                    wall[r + 2, col] = true;
                } else if (c == '\\') {
                    wall[r, col] = true;
                    wall[r + 1, col + 1] = true;
                    wall[r + 2, col + 2] = true;
                }
            }
        }

        bool[,] visited = new bool[N, N];
        int regions = 0;
        int[] dr = { -1, 1, 0, 0 };
        int[] dc = { 0, 0, -1, 1 };

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (wall[i, j] || visited[i, j]) continue;

                regions++;
                Queue<(int r, int c)> q = new Queue<(int r, int c)>();
                q.Enqueue((i, j));
                visited[i, j] = true;

                while (q.Count > 0) {
                    var (r, c) = q.Dequeue();

                    for (int d = 0; d < 4; d++) {
                        int nr = r + dr[d];
                        int nc = c + dc[d];

                        if (nr >= 0 && nr < N && nc >= 0 && nc < N &&
                            !wall[nr, nc] && !visited[nr, nc]) {
                            visited[nr, nc] = true;
                            q.Enqueue((nr, nc));
                        }
                    }
                }
            }
        }

        return regions;
    }
}
```

