public class Solution {
    public bool IsMatch(string s, string p) {
        int n = s.Length, m = p.Length;
        bool[,] dp = new bool[n + 1, m + 1];
        dp[0, 0] = true;
        for (int j = 1; j <= m; j++) {
            if (p[j - 1] == '*') {
                dp[0, j] = dp[0, j - 2];
            }
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                char pc = p[j - 1];
                if (pc == '.' || pc == s[i - 1]) {
                    dp[i, j] = dp[i - 1, j - 1];
                } else if (pc == '*') {
                    // zero occurrences
                    dp[i, j] = dp[i, j - 2];
                    char prev = p[j - 2];
                    if (prev == '.' || prev == s[i - 1]) {
                        dp[i, j] = dp[i, j] || dp[i - 1, j];
                    }
                }
            }
        }
        return dp[n, m];
    }
}

