using System.Collections.Generic;
using System.Text;

public class Solution {
    public IList<string> RemoveInvalidParentheses(string s) {
        int open = 0, close = 0;
        foreach (char c in s) {
            if (c == '(') {
                open++;
            } else if (c == ')') {
                if (open > 0) open--;
                else close++;
            }
        }
        int minRemovals = open + close;
        var result = new HashSet<string>();
        Dfs(s, 0, 0, 0, minRemovals, new StringBuilder(), result);
        return new List<string>(result);
    }

    private void Dfs(string s, int index, int balance, int removed, int minRemovals, StringBuilder sb, HashSet<string> result) {
        if (removed > minRemovals || balance < 0) return;
        if (index == s.Length) {
            if (balance == 0 && removed == minRemovals) {
                result.Add(sb.ToString());
            }
            return;
        }

        char c = s[index];
        if (c == '(' || c == ')') {
            if (removed < minRemovals) {
                Dfs(s, index + 1, balance, removed + 1, minRemovals, sb, result);
            }

            if (c == '(') {
                sb.Append(c);
                Dfs(s, index + 1, balance + 1, removed, minRemovals, sb, result);
                sb.Length--;
            } else {
                if (balance > 0) {
                    sb.Append(c);
                    Dfs(s, index + 1, balance - 1, removed, minRemovals, sb, result);
                    sb.Length--;
                }
            }
        } else {
            sb.Append(c);
            Dfs(s, index + 1, balance, removed, minRemovals, sb, result);
            sb.Length--;
        }
    }
}
