public class Solution {
    public int RemovePalindromeSub(string s) {
        if (s.Length == 0) return 0;

        int left = 0;
        int right = s.Length - 1;

        while (left < right) {
            if (s[left] != s[right]) {
                return 2;
            }
            left++;
            right--;
        }

        return 1;
    }
}
