```csharp
using System.Collections.Generic;

public class Solution {
    public bool IsScramble(string s1, string s2) {
        int n = s1.Length;
        var memo = new Dictionary<int, bool>();

        bool Dfs(int i, int j, int len) {
            int key = (i * n + j) * n + len;
            if (memo.TryGetValue(key, out bool cached)) {
                return cached;
            }

            bool equal = true;
            for (int t = 0; t < len; t++) {
                if (s1[i + t] != s2[j + t]) {
                    equal = false;
                    break;
                }
            }
            if (equal) {
                memo[key] = true;
                return true;
            }

            int[] count = new int[26];
            for (int t = 0; t < len; t++) {
                count[s1[i + t] - 'a']++;
                count[s2[j + t] - 'a']--;
            }
            for (int c = 0; c < 26; c++) {
                if (count[c] != 0) {
                    memo[key] = false;
                    return false;
                }
            }

            for (int k = 1; k < len; k++) {
                if (Dfs(i, j, k) && Dfs(i + k, j + k, len - k)) {
                    memo[key] = true;
                    return true;
                }
                if (Dfs(i, j + len - k, k) && Dfs(i + k, j, len - k)) {
                    memo[key] = true;
                    return true;
                }
            }

            memo[key] = false;
            return false;
        }

        return Dfs(0, 0, n);
    }
}
```

