```csharp
using System;
using System.Collections.Generic;

public class Solution {
    public IList<IList<string>> SuggestedProducts(string[] products, string searchWord) {
        Array.Sort(products, StringComparer.Ordinal);
        var result = new List<IList<string>>();
        string prefix = "";

        for (int i = 0; i < searchWord.Length; i++) {
            prefix += searchWord[i];

            int lo = 0, hi = products.Length;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (String.CompareOrdinal(products[mid], prefix) < 0) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }

            var suggestions = new List<string>();
            for (int j = lo; j < products.Length && suggestions.Count < 3; j++) {
                if (products[j].StartsWith(prefix, StringComparison.Ordinal)) {
                    suggestions.Add(products[j]);
                } else {
                    break;
                }
            }

            result.Add(suggestions);
        }

        return result;
    }
}
```

