public class Solution {
    public double[] MedianSlidingWindow(int[] nums, int k) {
        int n = nums.Length;
        int[] sorted = nums.Distinct().OrderBy(x => x).ToArray();
        int m = sorted.Length;

        Dictionary<int, int> rank = new Dictionary<int, int>(m);
        for (int i = 0; i < m; i++) {
            rank[sorted[i]] = i + 1;
        }

        int[] bit = new int[m + 1];

        void Add(int idx, int delta) {
            while (idx <= m) {
                bit[idx] += delta;
                idx += idx & -idx;
            }
        }

        int FindKth(int target) {
            int idx = 0;
            int mask = 1;
            while ((mask << 1) <= m) {
                mask <<= 1;
            }

            while (mask != 0) {
                int next = idx + mask;
                if (next <= m && bit[next] < target) {
                    idx = next;
                    target -= bit[next];
                }
                mask >>= 1;
            }

            return idx + 1;
        }

        double[] result = new double[n - k + 1];
        int pos = 0;

        for (int i = 0; i < n; i++) {
            Add(rank[nums[i]], 1);

            if (i >= k) {
                Add(rank[nums[i - k]], -1);
            }

            if (i >= k - 1) {
                if ((k & 1) == 1) {
                    int idx = FindKth((k + 1) / 2);
                    result[pos++] = sorted[idx - 1];
                } else {
                    int idx1 = FindKth(k / 2);
                    int idx2 = FindKth(k / 2 + 1);
                    result[pos++] = ((double)sorted[idx1 - 1] + sorted[idx2 - 1]) / 2.0;
                }
            }
        }

        return result;
    }
}
