public class Solution {
    public int SplitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        foreach (int n in nums) {
            if (n > lo) lo = n;
            hi += n;
        }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (CanSplit(nums, k, mid)) hi = mid;
            else lo = mid + 1;
        }
        return (int)lo;
    }
    private bool CanSplit(int[] nums, int k, long limit) {
        int count = 1;
        long current = 0;
        foreach (int n in nums) {
            if (current + n > limit) {
                count++;
                current = n;
                if (count > k) return false;
            } else {
                current += n;
            }
        }
        return true;
    }
}

