using System;
using System.Collections.Generic;
using System.Text;

public class Solution {
    private Dictionary<string, int> memo;
    private List<int[]> stickerCounts;

    public int MinStickers(string[] stickers, string target) {
        if (string.IsNullOrEmpty(target)) return 0;

        memo = new Dictionary<string, int>();

        int[] targetTotal = new int[26];
        foreach (char c in target) {
            targetTotal[c - 'a']++;
        }

        var seen = new HashSet<string>();
        stickerCounts = new List<int[]>();

        foreach (string s in stickers) {
            if (!seen.Add(s)) continue;

            int[] cnt = new int[26];
            foreach (char c in s) {
                int idx = c - 'a';
                if (targetTotal[idx] > 0) {
                    cnt[idx]++;
                    if (cnt[idx] > targetTotal[idx]) {
                        cnt[idx] = targetTotal[idx];
                    }
                }
            }

            bool any = false;
            for (int i = 0; i < 26; i++) {
                if (cnt[i] > 0) {
                    any = true;
                    break;
                }
            }

            if (any) stickerCounts.Add(cnt);
        }

        string start = SortString(target);
        return Dfs(start);
    }

    private string SortString(string s) {
        int[] cnt = new int[26];
        foreach (char c in s) {
            cnt[c - 'a']++;
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < cnt[i]; j++) {
                sb.Append((char)('a' + i));
            }
        }

        return sb.ToString();
    }

    private int Dfs(string remain) {
        if (remain.Length == 0) return 0;
        if (memo.TryGetValue(remain, out int cached)) return cached;

        int[] cnt = new int[26];
        foreach (char c in remain) {
            cnt[c - 'a']++;
        }

        int firstIdx = remain[0] - 'a';
        int best = int.MaxValue;

        foreach (int[] sticker in stickerCounts) {
            if (sticker[firstIdx] == 0) continue;

            int[] nextCnt = (int[])cnt.Clone();
            bool used = false;

            for (int i = 0; i < 26; i++) {
                if (sticker[i] > 0 && nextCnt[i] > 0) {
                    int take = sticker[i] < nextCnt[i] ? sticker[i] : nextCnt[i];
                    nextCnt[i] -= take;
                    used = true;
                }
            }

            if (!used) continue;

            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 26; i++) {
                for (int j = 0; j < nextCnt[i]; j++) {
                    sb.Append((char)('a' + i));
                }
            }

            int sub = Dfs(sb.ToString());
            if (sub != -1) {
                best = Math.Min(best, sub + 1);
            }
        }

        if (best == int.MaxValue) best = -1;
        memo[remain] = best;
        return best;
    }
}
