using System;
using System.Text;

public class StreamChecker {
    private int[] next;
    private bool[] isWord;
    private int maxLen;
    private StringBuilder stream;

    public StreamChecker(string[] words) {
        int total = 0;
        foreach (string w in words) {
            total += w.Length;
        }

        next = new int[(total + 1) * 26];
        for (int i = 0; i < next.Length; i++) {
            next[i] = -1;
        }

        isWord = new bool[total + 1];
        int nodeCount = 1;
        maxLen = 0;

        foreach (string w in words) {
            if (w.Length > maxLen) {
                maxLen = w.Length;
            }

            int node = 0;
            for (int i = w.Length - 1; i >= 0; i--) {
                int c = w[i] - 'a';
                int idx = node * 26 + c;
                if (next[idx] == -1) {
                    next[idx] = nodeCount++;
                }
                node = next[idx];
            }
            isWord[node] = true;
        }

        stream = new StringBuilder();
    }

    public bool Query(char letter) {
        stream.Append(letter);

        int node = 0;
        int start = stream.Length - 1;
        int limit = Math.Max(0, stream.Length - maxLen);

        for (int i = start; i >= limit; i--) {
            int c = stream[i] - 'a';
            int nextNode = next[node * 26 + c];
            if (nextNode == -1) {
                return false;
            }
            node = nextNode;
            if (isWord[node]) {
                return true;
            }
        }

        return false;
    }
}
```

