public class Solution {
    public int SumOddLengthSubarrays(int[] arr) {
        int n = arr.Length;
        int result = 0;

        for (int i = 0; i < n; i++) {
            int left = i + 1;
            int right = n - i;
            int oddCount = (left * right + 1) / 2;
            result += arr[i] * oddCount;
        }

        return result;
    }
}
