```csharp
using System;
using System.Collections.Generic;

public class Solution {
    private int[,,] memoMin;
    private int[,,] memoMax;
    private int Nmax = 30;

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memoMin = new int[30,30,30];
        memoMax = new int[30,30,30];
        for (int i=0; i<30; i++)
          for (int j=0; j<30; j++)
            for (int k=0; k<30; k++)
              memoMin[i,j,k] = -1;
        var res = Dfs(n, firstPlayer, secondPlayer);
        return new int[] { res.Item1, res.Item2 };
    }

    private (int, int) Dfs(int n, int l, int r) {
        if (l + r == n + 1) return (1,1);
        if (memoMin[n,l,r] != -1) return (memoMin[n,l,r], memoMax[n,l,r]);
        int min = int.MaxValue;
        int max = int.MinValue;
        int m = (n + 1) / 2;
        List<int> survivors = new List<int>();
        void Rec(int i) {
            if (i > n / 2) {
                if (n % 2 == 1) survivors.Add(n / 2 + 1);
                survivors.Sort();
                int nl = survivors.IndexOf(l) + 1;
                int nr = survivors.IndexOf(r) + 1;
                var sub = Dfs(m, nl, nr);
                if (1 + sub.Item1 < min) min = 1 + sub.Item1;
                if (1 + sub.Item2 > max) max = 1 + sub.Item2;
                if (n % 2 == 1) survivors.RemoveAt(survivors.Count - 1);
                return;
            }
            int a = i;
            int b = n + 1 - i;
            if (a == l || b == l) {
                survivors.Add(l);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
            } else if (a == r || b == r) {
                survivors.Add(r);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
            } else {
                survivors.Add(a);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
                survivors.Add(b);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
            }
        }
        Rec(1);
        memoMin[n,l,r] = min;
        memoMax[n,l,r] = max;
        return (min, max);
    }
}
```

