using System;
using System.Collections.Generic;

public class Solution {
    private int[,,] memoMin;
    private int[,,] memoMax;

    public int[] EarliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        memoMin = new int[30,30,30];
        memoMax = new int[30,30,30];
        for (int i = 0; i < 30; i++)
            for (int j = 0; j < 30; j++)
                for (int k = 0; k < 30; k++)
                    memoMin[i,j,k] = -1;
        var ans = Dfs(n, firstPlayer, secondPlayer);
        return new int[] { ans.Item1, ans.Item2 };
    }

    private (int, int) Dfs(int n, int l, int r) {
        if (l + r == n + 1) return (1, 1);
        if (memoMin[n, l, r] != -1) return (memoMin[n, l, r], memoMax[n, l, r]);

        int min = int.MaxValue;
        int max = int.MinValue;
        int m = (n + 1) / 2;
        List<int> survivors = new List<int>();

        void Rec(int i) {
            if (i > n / 2) {
                List<int> list = new List<int>(survivors);
                if (n % 2 == 1) list.Add(n / 2 + 1);
                list.Sort();
                int nl = list.IndexOf(l) + 1;
                int nr = list.IndexOf(r) + 1;
                var sub = Dfs(m, nl, nr);
                int earliest = 1 + sub.Item1;
                int latest = 1 + sub.Item2;
                if (earliest < min) min = earliest;
                if (latest > max) max = latest;
                return;
            }

            int a = i;
            int b = n + 1 - i;

            if (a == l || b == l) {
                survivors.Add(l);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
            } else if (a == r || b == r) {
                survivors.Add(r);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
            } else {
                survivors.Add(a);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);

                survivors.Add(b);
                Rec(i + 1);
                survivors.RemoveAt(survivors.Count - 1);
            }
        }

        Rec(1);

        memoMin[n, l, r] = min;
        memoMax[n, l, r] = max;
        return (min, max);
    }
}
