```csharp
public class Solution {
    public bool ValidateBinaryTreeNodes(int n, int[] leftChild, int[] rightChild) {
        int[] indegree = new int[n];
        for (int i = 0; i < n; i++) {
            int l = leftChild[i];
            if (l != -1) {
                indegree[l]++;
                if (indegree[l] > 1) return false;
            }
            int r = rightChild[i];
            if (r != -1) {
                indegree[r]++;
                if (indegree[r] > 1) return false;
            }
        }

        int root = -1;
        for (int i = 0; i < n; i++) {
            if (indegree[i] == 0) {
                if (root != -1) return false;
                root = i;
            }
        }
        if (root == -1) return false;

        bool[] visited = new bool[n];
        int[] stack = new int[n];
        int top = 0;
        stack[top++] = root;
        int count = 0;

        while (top > 0) {
            int node = stack[--top];
            if (visited[node]) return false;
            visited[node] = true;
            count++;

            if (leftChild[node] != -1) stack[top++] = leftChild[node];
            if (rightChild[node] != -1) stack[top++] = rightChild[node];
        }

        return count == n;
    }
}
```

