public class Solution {
    private int[] charDigit = new int[26];
    private bool[] used = new bool[10];
    private bool[] leading = new bool[26];
    private string[] words;
    private string result;
    private int maxLen;

    public bool IsSolvable(string[] words, string result) {
        this.words = words;
        this.result = result;
        Array.Fill(charDigit, -1);
        Array.Clear(used, 0, used.Length);
        Array.Clear(leading, 0, leading.Length);

        maxLen = result.Length;
        foreach (string w in words) {
            if (w.Length > maxLen) maxLen = w.Length;
            if (w.Length > 1) leading[w[0] - 'A'] = true;
        }
        if (result.Length > 1) leading[result[0] - 'A'] = true;

        return Dfs(0, 0);
    }

    private bool Dfs(int col, int carry) {
        if (col == maxLen) return carry == 0;

        List<int> unassigned = new List<int>();
        bool[] seen = new bool[26];

        foreach (string w in words) {
            if (col < w.Length) {
                int c = w[w.Length - 1 - col] - 'A';
                if (charDigit[c] == -1 && !seen[c]) {
                    seen[c] = true;
                    unassigned.Add(c);
                }
            }
        }

        return Assign(col, carry, unassigned, 0);
    }

    private bool Assign(int col, int carry, List<int> chars, int idx) {
        if (idx == chars.Count) {
            int sum = carry;
            foreach (string w in words) {
                if (col < w.Length) {
                    int c = w[w.Length - 1 - col] - 'A';
                    sum += charDigit[c];
                }
            }

            int expected = sum % 10;
            int newCarry = sum / 10;

            if (col < result.Length) {
                int rc = result[result.Length - 1 - col] - 'A';
                if (charDigit[rc] == -1) {
                    if (used[expected]) return false;
                    if (leading[rc] && expected == 0) return false;
                    charDigit[rc] = expected;
                    used[expected] = true;
                    bool ok = Dfs(col + 1, newCarry);
                    used[expected] = false;
                    charDigit[rc] = -1;
                    return ok;
                } else {
                    if (charDigit[rc] != expected) return false;
                    return Dfs(col + 1, newCarry);
                }
            } else {
                if (expected != 0) return false;
                return Dfs(col + 1, newCarry);
            }
        }

        int ch = chars[idx];
        for (int d = 0; d <= 9; d++) {
            if (used[d]) continue;
            if (leading[ch] && d == 0) continue;
            charDigit[ch] = d;
            used[d] = true;
            if (Assign(col, carry, chars, idx + 1)) return true;
            used[d] = false;
            charDigit[ch] = -1;
        }

        return false;
    }
}
